#include <stdio.h>
#define MAX 5

typedef struct {
    int data[MAX];
    int front;
    int rear;
} Queue;

void initQueue(Queue *q) {
    q->front = 0;
    q->rear = 0;
}

int isEmpty(const Queue *q) {
    return q->front == q->rear;
}

int isFull(const Queue *q) {
    return q->rear == MAX;
}

int enqueue(Queue *q, int value) {
    if (isFull(q)) return 0; // overflow
    q->data[q->rear++] = value;
    return 1;
}

int dequeue(Queue *q, int *value) {
    if (isEmpty(q)) return 0; // underflow
    *value = q->data[q->front++];
    // optional reset when queue becomes empty to reuse array space
    if (isEmpty(q)) {
        q->front = q->rear = 0;
    }
    return 1;
}

int main(void) {
    Queue q;
    initQueue(&q);
    enqueue(&q, 10);
    enqueue(&q, 20);
    enqueue(&q, 30);
    int v;
    dequeue(&q, &v); printf("%d\n", v);
    dequeue(&q, &v); printf("%d\n", v);
    enqueue(&q, 40);
    enqueue(&q, 50);
    while (!isEmpty(&q)) {
        dequeue(&q, &v);
        printf("%d\n", v);
    }
    return 0;
}

