#include <stdio.h>
#define CAP 5

typedef struct {
    int data[CAP];
    int front; // points to current front element
    int rear;  // points to position where next rear element will be inserted
    int size;  // number of stored elements
} Deque;

void initDeque(Deque *d) {
    d->front = 0;
    d->rear = 0;
    d->size = 0;
}

int isEmpty(const Deque *d) { return d->size == 0; }
int isFull(const Deque *d) { return d->size == CAP; }

int pushFront(Deque *d, int x) {
    if (isFull(d)) return 0;
    d->front = (d->front - 1 + CAP) % CAP;
    d->data[d->front] = x;
    d->size++;
    return 1;
}

int pushRear(Deque *d, int x) {
    if (isFull(d)) return 0;
    d->data[d->rear] = x;
    d->rear = (d->rear + 1) % CAP;
    d->size++;
    return 1;
}

int popFront(Deque *d, int *x) {
    if (isEmpty(d)) return 0;
    *x = d->data[d->front];
    d->front = (d->front + 1) % CAP;
    d->size--;
    return 1;
}

int popRear(Deque *d, int *x) {
    if (isEmpty(d)) return 0;
    d->rear = (d->rear - 1 + CAP) % CAP;
    *x = d->data[d->rear];
    d->size--;
    return 1;
}

int main(void) {
    Deque d;
    initDeque(&d);
    pushRear(&d, 1);
    pushRear(&d, 2);
    pushFront(&d, 3);
    int v;
    popRear(&d, &v); printf("%d\n", v);
    popFront(&d, &v); printf("%d\n", v);
    pushFront(&d, 4);
    pushRear(&d, 5);
    popFront(&d, &v); printf("%d\n", v);
    popRear(&d, &v); printf("%d\n", v);
    return 0;
}

